// Inference-only MLP accelerator: N_IN -> H_HID (tanh) -> 1 (tanh).
//
// Bit-exact contract shared with python/fixedpoint.py and
// Zynq7K/Software/ann_ref.cpp:
//   acc = sum_i w[i]*x[i] + b      (exact, 48 fractional bits)
//   z   = fix_t(acc)               (round half even, saturate to Q8.24)
//   y   = TANH_LUT_RAW[clamp((z_raw + (8<<24)) >> 16, 0, 4095)]
#ifndef TOPANN_H
#define TOPANN_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <stdint.h>

#include "model_params.h"   // N_IN, H_HID, weights (generated by python/export.py)
#include "tanh_lut.h"       // TANH_LUT_RAW[4096]  (generated by python/export.py)

typedef ap_fixed<32, 8, AP_RND_CONV, AP_SAT> fix_t;   // Q8.24
typedef ap_fixed<72, 24> acc_t;                        // exact sum of Q16.48 products

// Pre-activation of hidden neuron j, Q8.24 (before tanh). Separate so the
// testbench can check the rounding, which the tanh table hides at the output.
fix_t hidden_preact(const fix_t inputs[N_IN], const fix_t w1[H_HID * N_IN], const fix_t b1[H_HID], int j);

// All ports are AXI4-Lite (bundle CTRL): no AXI master, no shared DDR buffers.
// w1 is row-major: w1[j * N_IN + i] = weight from input i to hidden neuron j.
void topann(const fix_t inputs[N_IN],
            const fix_t w1[H_HID * N_IN],
            const fix_t b1[H_HID],
            const fix_t w2[H_HID],
            fix_t b2,
            fix_t *result);

#endif
